# django/utils/timezone.py

from datetime import datetime
import pytz
from django.conf import settings

class Timezone:
    @staticmethod
    def get_current_timezone():
        return pytz.timezone(settings.TIME_ZONE)

    @staticmethod
    def to_current_timezone(dt):
        """Convert a datetime object to the current timezone."""
        current_tz = Timezone.get_current_timezone()
        if dt.tzinfo is None:
            dt = current_tz.localize(dt)
        else:
            dt = dt.astimezone(current_tz)
        return dt

    @staticmethod
    def from_current_timezone(dt):
        """Convert a datetime object from the current timezone to UTC."""
        current_tz = Timezone.get_current_timezone()
        if dt.tzinfo is None:
            dt = current_tz.localize(dt)
        return dt.astimezone(pytz.utc)
