def recursive_diff(dict1, dict2, log=False):
    """
    Recursively computes the difference between two dictionaries.

    Args:
    dict1 (dict): The first dictionary.
    dict2 (dict): The second dictionary.
    log (bool): Whether to log the differences. Defaults to False.

    Returns:
    dict: A dictionary containing the differences.
    """
    if not isinstance(dict1, dict) or not isinstance(dict2, dict):
        if log:
            print("Difference found: {} != {}".format(dict1, dict2))
        return dict1 if dict1 != dict2 else {}

    diff = {}
    for key in set(dict1) | set(dict2):
        if key not in dict1:
            diff[key] = dict2[key]
            if log:
                print("Key '{}' added: {}".format(key, dict2[key]))
        elif key not in dict2:
            diff[key] = dict1[key]
            if log:
                print("Key '{}' removed: {}".format(key, dict1[key]))
        elif isinstance(dict1[key], dict) and isinstance(dict2[key], dict):
            sub_diff = recursive_diff(dict1[key], dict2[key], log)
            if sub_diff:
                diff[key] = sub_diff
        elif dict1[key] != dict2[key]:
            diff[key] = dict2[key]
            if log:
                print("Value for key '{}' changed: {} -> {}".format(key, dict1[key], dict2[key]))

    return diff
